mapper.select:
/* selectMasterMdCmMsdsEmailSentList */
SELECT A.SEQ, A.BUYER, (SELECT C.COM_NAME_LOC FROM ICOMCMPY C WHERE C.COM_CODE = A.BUYER) AS BUYER_NAME, A.BUYER_ITEM_NO, A.PO_NO, A.PO_SEQ, A.MAIL_RECV_YN, TO_CHAR(A.SEND_DATE, 'YYYY/MM/DD HH24:MI') AS SEND_DATE, TO_CHAR(A.RECV_DATE, 'YYYY/MM/DD HH24:MI') AS RECV_DATE, A.RECV_NAME, A.RECV_EMAIL, TO_CHAR(A.ADD_DATE, 'YYYY/MM/DD HH24:MI') AS ADD_DATE, A.ADD_USER_ID, (SELECT U.USER_NAME_LOC FROM ICOMLUSR U WHERE U.USER_ID = A.ADD_USER_ID) AS ADD_USER_NAME, TO_CHAR(A.CHANGE_DATE, 'YYYY/MM/DD HH24:MI') AS CHANGE_DATE, A.CHANGE_USER_ID, (SELECT U.USER_NAME_LOC FROM ICOMLUSR U WHERE U.USER_ID = A.CHANGE_USER_ID) AS CHANGE_USER_NAME, A.BYIT_COMORG_CODE, A.REG_TYPE, (SELECT C.TEXT1 FROM ICOMCOD1 C WHERE C.TYPE = 'CM12' AND C.CODE = A.REG_TYPE) AS REG_TYPE_NAME, B.DESCRIPTION_LOC, B.SPECIFICATION, B.MAKER_PART_NO, B.MAKER_CODE, B.MAKER_NAME, B.ORIGIN_CODE, DECODE(B.ORIGIN_CODE,'','',(SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = B.ORIGIN_CODE)) AS ORIGIN_NAME, B.UNIT_MEASURE FROM KEP_CMC_MAILSEND A, ICOMBYIT B WHERE 1=1 AND A.BYIT_COMORG_CODE = B.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND TO_CHAR(A.SEND_DATE, 'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BUYER = #{st_buyer_code}
AND UPPER(A.RECV_NAME) LIKE UPPER( '%' || #{st_recv_name} || '%')
AND UPPER(A.BUYER_ITEM_NO) LIKE UPPER( '%' || #{st_buyer_item_no} || '%')
AND A.MAIL_RECV_YN = #{st_mail_recv_yn}
ORDER BY A.BUYER, A.RECV_NAME, A.ADD_DATE
